  "response_type": "answer",
  "answer": "Employees leaving the company must return company equipment within 10 business days unless HR Admin approves an extension. Damaged or missing equipment is reviewed by HR Admin and IT Admin before any payroll or final-pay action, and this policy does not authorize payroll deductions automatically for missing laptops.",
  "citations": [
    {
      "document_id": "OPS-001",
      "document_title": "Vendor, Travel, and Equipment Operations Policy",
      "section_heading": "Shipping and Return Rules",
      "chunk_id": "7f43621b-e723-47b9-b347-6c633696ca67",
      "citation_text": "Employees leaving the company must return company equipment within 10 business days unless HR Admin approves an extension. Damaged or missing equipment is reviewed by HR Admin and IT Admin before any payroll or final-pay action. This policy does not authorize payroll deductions by itself."
    }
  ],
  "supported_claims": [
    "Equipment-return deadline is 10 business days",
    "HR Admin can approve extensions",
    "Missing laptop does not automatically authorize payroll deduction"
  ],
  "unsupported_claims": [],
  "validation_notes": "The policy clearly states the deadline and extension authority, and that payroll deductions are not automatic for missing equipment."
}
